import { useCallback,useEffect,useState } from 'react';import type {LibraryQuery} from '../api/types.ts';
function read():LibraryQuery{const p=new URLSearchParams(location.search);return{view:p.get('view')==='archived'?'archived':'active',q:(p.get('q')??'').slice(0,200),tags:p.getAll('tag'),favorite:p.get('favorite')==='true',sort:['oldest','title'].includes(p.get('sort')??'')?p.get('sort') as 'oldest'|'title':'newest'}}
export function useLibraryViewState(){const [query,setQuery]=useState(read);useEffect(()=>{const fn=()=>setQuery(read());addEventListener('popstate',fn);return()=>removeEventListener('popstate',fn)},[]);const update=useCallback((patch:Partial<LibraryQuery>)=>setQuery(current=>{const next={...current,...patch};const p=new URLSearchParams();if(next.view!=='active')p.set('view',next.view);if(next.q)p.set('q',next.q);next.tags.forEach(t=>p.append('tag',t));if(next.favorite)p.set('favorite','true');if(next.sort!=='newest')p.set('sort',next.sort);history.pushState(null,'',`${location.pathname}${p.size?`?${p}`:''}`);return next}),[]);return{query,update};}

