import { useEffect,useRef,useState } from 'react';import { preview } from '../api/bookmarks.ts';import type {MetadataPreview} from '../api/types.ts';import { normalizeBookmarkUrl } from '../../shared/url/normalize.ts';import { mayApplyMetadata } from './metadataFormState.ts';
export function useMetadataPreview(url:string,dirty:{title:boolean;description:boolean},apply:{title:(v:string)=>void;description:(v:string)=>void}){
  const [state,setState]=useState<{loading:boolean;result:MetadataPreview|null}>({loading:false,result:null});const generation=useRef(0);
  useEffect(()=>{let normalized;try{normalized=normalizeBookmarkUrl(url).url}catch{setState({loading:false,result:null});return}const requested=url;const id=++generation.current;const controller=new AbortController();const timer=setTimeout(async()=>{setState({loading:true,result:null});try{const result=await preview(normalized,controller.signal);if(id!==generation.current)return;setState({loading:false,result});if(result.title&&mayApplyMetadata(requested,url,dirty.title))apply.title(result.title);if(result.description&&mayApplyMetadata(requested,url,dirty.description))apply.description(result.description);}catch{if(!controller.signal.aborted)setState({loading:false,result:{normalizedUrl:normalized,status:'unavailable',title:null,description:null,message:'We couldn’t load page details. You can still save this bookmark.'}})}},url.trim()?350:0);return()=>{clearTimeout(timer);controller.abort()}},[url]);
  return state;
}

